import re

def _parse_ip(ip: str) -> int:
    parts = ip.split('.')
    if len(parts) != 4:
        raise ValueError(f"Invalid IPv4 address: {ip!r}")
    value = 0
    for part in parts:
        if not re.fullmatch(r'\d+', part):
            raise ValueError(f"Invalid octet: {part!r} in {ip!r}")
        num = int(part)
        if num < 0 or num > 255:
            raise ValueError(f"Octet out of range: {part!r} in {ip!r}")
        value = (value << 8) | num
    return value


def cidr_contains(cidr: str, ip: str) -> bool:
    if '/' not in cidr:
        raise ValueError(f"Missing slash in CIDR: {cidr!r}")
    net_part, prefix_part = cidr.split('/', 1)

    if not re.fullmatch(r'\d+', prefix_part):
        raise ValueError(f"Invalid prefix length: {prefix_part!r}")
    prefix_len = int(prefix_part)
    if prefix_len < 0 or prefix_len > 32:
        raise ValueError(f"Prefix length out of range: {prefix_len}")

    net_int = _parse_ip(net_part)
    ip_int = _parse_ip(ip)

    if prefix_len == 0:
        mask = 0
    else:
        mask = (0xFFFFFFFF << (32 - prefix_len)) & 0xFFFFFFFF

    return (net_int & mask) == (ip_int & mask)
